import{_ as e,c as r,o as i,a0 as l}from"./chunks/framework.DKRgXLPU.js";const a=JSON.parse('{"title":"Competition Preparation","description":"Prepare optimally for pétanque competitions. Learn the physical, mental, and tactical preparation that sets you up for peak performance.","frontmatter":{"title":"Competition Preparation","description":"Prepare optimally for pétanque competitions. Learn the physical, mental, and tactical preparation that sets you up for peak performance."},"headers":[],"relativePath":"da/blog/competition-prep.md","filePath":"da/blog/competition-prep.md"}');const n=e({name:"da/blog/competition-prep.md"},[["render",function(e,a,n,t,s,o){return i(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="konkurrenceforberedelse" tabindex="-1">Konkurrenceforberedelse <a class="header-anchor" href="#konkurrenceforberedelse" aria-label="Permalink to &quot;Konkurrenceforberedelse&quot;">​</a></h1><p>Kampen starter ikke, når du kaster den første kugle – den starter dage før. Hvordan du forbereder dig op til konkurrencen påvirker din præstation betydeligt. Elitespillere overlader ikke forberedelsen til tilfældighederne.</p><h2 id="forberedelsestidslinjen" tabindex="-1">Forberedelsestidslinjen <a class="header-anchor" href="#forberedelsestidslinjen" aria-label="Permalink to &quot;Forberedelsestidslinjen&quot;">​</a></h2><h3 id="en-uge-før" tabindex="-1">En uge før <a class="header-anchor" href="#en-uge-før" aria-label="Permalink to &quot;En uge før&quot;">​</a></h3><p><strong>Fysisk:</strong></p><ul><li>Oprethold normal træningsintensitet</li><li>Sørg for tilstrækkelig hvile</li><li>Håndter eventuelle mindre fysiske problemer</li></ul><p><strong>Mental:</strong></p><ul><li>Visualiser succesfuld præstation</li><li>Gennemgå målene for konkurrencen</li><li>Begynd at fokusere opmærksomheden</li></ul><p><strong>Taktisk:</strong></p><ul><li>Undersøg modstandere, hvis det er muligt</li><li>Gennemgå din spilleplan</li><li>Diskuter strategi med holdkammerater</li></ul><h3 id="to-dage-før" tabindex="-1">To dage før <a class="header-anchor" href="#to-dage-før" aria-label="Permalink to &quot;To dage før&quot;">​</a></h3><p><strong>Fysisk:</strong></p><ul><li>Reducer træningsintensiteten</li><li>Fokuser på at have det godt, ikke på at forbedre dig</li><li>Prioriter søvn</li></ul><p><strong>Mental:</strong></p><ul><li>Øg visualiseringspraksis</li><li>Håndter nerverne før konkurrencen</li><li>Forbliv positiv og selvsikker</li></ul><p><strong>Logistisk:</strong></p><ul><li>Forbered udstyr</li><li>Planlæg rejse og tidsplan</li><li>Håndter administrative detaljer</li></ul><h3 id="dagen-før" tabindex="-1">Dagen før <a class="header-anchor" href="#dagen-før" aria-label="Permalink to &quot;Dagen før&quot;">​</a></h3><p><strong>Fysisk:</strong></p><ul><li>Kun let træning</li><li>Hvile og restitution</li><li>God ernæring og hydrering</li></ul><p><strong>Mental:</strong></p><ul><li>Afsluttende visualiseringssession</li><li>Afslapningsteknikker</li><li>Positiv selvsnak</li></ul><p><strong>Praktisk:</strong></p><ul><li>Bekræft al logistik</li><li>Forbered hvad du skal have på</li><li>Indstil alarmer og påmindelser</li></ul><h3 id="konkurrencedag" tabindex="-1">Konkurrencedag <a class="header-anchor" href="#konkurrencedag" aria-label="Permalink to &quot;Konkurrencedag&quot;">​</a></h3><p><strong>Morgen:</strong></p><ul><li>Vågn op i god tid</li><li>Spis velkendte, gennemprøvede fødevarer</li><li>Begynd mental forberedelse</li></ul><p><strong>Før kampen:</strong></p><ul><li>Ankom tidligt</li><li>Bliv fortrolig med terrænet</li><li>Komplet opvarmningsrutine</li><li>Endelig holdopstilling</li></ul><h2 id="fysisk-forberedelse" tabindex="-1">Fysisk forberedelse <a class="header-anchor" href="#fysisk-forberedelse" aria-label="Permalink to &quot;Fysisk forberedelse&quot;">​</a></h2><h3 id="sove" tabindex="-1">Sove <a class="header-anchor" href="#sove" aria-label="Permalink to &quot;Sove&quot;">​</a></h3><p>Søvn er brændstof til præstation:</p><ul><li>Prioriter 7-9 timer i dagene før</li><li>Oprethold en konsekvent søvnplan</li><li>Undgå alkohol og skærme før sengetid</li></ul><h3 id="ernæring" tabindex="-1">Ernæring <a class="header-anchor" href="#ernæring" aria-label="Permalink to &quot;Ernæring&quot;">​</a></h3><p>Giv din præstation styrke:</p><ul><li>Spis velkendte fødevarer (ikke eksperimentelle)</li><li>Hold dig hydreret</li><li>Undgå tunge måltider tæt på leg</li><li>Hav snacks klar under konkurrencen</li></ul><h3 id="fysisk-parathed" tabindex="-1">Fysisk parathed <a class="header-anchor" href="#fysisk-parathed" aria-label="Permalink to &quot;Fysisk parathed&quot;">​</a></h3><p>Mød op klar til at optræde:</p><ul><li>Afhjælp eventuelle skader eller ubehag</li><li>Varm ordentligt op</li><li>Hold dig afslappet mellem kampene</li></ul><h2 id="mental-forberedelse" tabindex="-1">Mental forberedelse <a class="header-anchor" href="#mental-forberedelse" aria-label="Permalink to &quot;Mental forberedelse&quot;">​</a></h2><h3 id="visualisering" tabindex="-1">Visualisering <a class="header-anchor" href="#visualisering" aria-label="Permalink to &quot;Visualisering&quot;">​</a></h3><p>Se succes før den sker:</p><ul><li>Visualiser specifikke scenarier, du kan stå over for</li><li>Se dig selv håndtere pres godt</li><li>Føl selvtilliden ved en god præstation</li></ul><h3 id="malsætning" tabindex="-1">Målsætning <a class="header-anchor" href="#malsætning" aria-label="Permalink to &quot;Målsætning&quot;">​</a></h3><p>Vid hvad du sigter efter:</p><ul><li>Resultatmål (hvad du ønsker at opnå)</li><li>Procesmål (hvordan du vil spille)</li><li>Fokusmål (hvor opmærksomheden går hen)</li></ul><h3 id="opbygning-af-tillid" tabindex="-1">Opbygning af tillid <a class="header-anchor" href="#opbygning-af-tillid" aria-label="Permalink to &quot;Opbygning af tillid&quot;">​</a></h3><p>Deltag i konkurrencen, tro på dig selv:</p><ul><li>Gennemgå tidligere succeser</li><li>Bekræft din forberedelse</li><li>Fokus på styrker</li></ul><h3 id="angsthandtering" tabindex="-1">Angsthåndtering <a class="header-anchor" href="#angsthandtering" aria-label="Permalink to &quot;Angsthåndtering&quot;">​</a></h3><p>Kanaliser nerver produktivt:</p><ul><li>Anerkend angst som normalt</li><li>Brug vejrtrækningsteknikker</li><li>Omformuler nerver til spænding</li></ul><h2 id="taktisk-forberedelse" tabindex="-1">Taktisk forberedelse <a class="header-anchor" href="#taktisk-forberedelse" aria-label="Permalink to &quot;Taktisk forberedelse&quot;">​</a></h2><h3 id="kend-dit-spil" tabindex="-1">Kend dit spil <a class="header-anchor" href="#kend-dit-spil" aria-label="Permalink to &quot;Kend dit spil&quot;">​</a></h3><p>Vær tydelig i din tilgang:</p><ul><li>Hvad er dit holds stil?</li><li>Hvad er dine styrker at udnytte?</li><li>Hvilke svagheder skal håndteres?</li></ul><h3 id="kend-konkurrencen" tabindex="-1">Kend konkurrencen <a class="header-anchor" href="#kend-konkurrencen" aria-label="Permalink to &quot;Kend konkurrencen&quot;">​</a></h3><p>Indsaml nyttige oplysninger:</p><ul><li>Modstandernes tendenser</li><li>Terrænegenskaber</li><li>Konkurrenceformat og regler</li></ul><h3 id="hav-en-plan" tabindex="-1">Hav en plan <a class="header-anchor" href="#hav-en-plan" aria-label="Permalink to &quot;Hav en plan&quot;">​</a></h3><p>Gå ind med klare intentioner:</p><ul><li>Åbningsstrategi</li><li>Justeringer for forskellige scenarier</li><li>Roller og ansvarsområder</li></ul><h2 id="holdforberedelse" tabindex="-1">Holdforberedelse <a class="header-anchor" href="#holdforberedelse" aria-label="Permalink to &quot;Holdforberedelse&quot;">​</a></h2><h3 id="justering" tabindex="-1">Justering <a class="header-anchor" href="#justering" aria-label="Permalink to &quot;Justering&quot;">​</a></h3><p>Sørg for, at alle er på samme bølgelængde:</p><ul><li>Fælles mål</li><li>Tydelige roller</li><li>Aftalt kommunikationstilgang</li></ul><h3 id="støttesystemer" tabindex="-1">Støttesystemer <a class="header-anchor" href="#støttesystemer" aria-label="Permalink to &quot;Støttesystemer&quot;">​</a></h3><p>Opret gensidig støtte:</p><ul><li>Hvordan vil I opmuntre hinanden?</li><li>Hvordan vil du håndtere tilbageslag?</li><li>Hvordan ser support ud?</li></ul><h3 id="logistik" tabindex="-1">Logistik <a class="header-anchor" href="#logistik" aria-label="Permalink to &quot;Logistik&quot;">​</a></h3><p>Håndter praktiske ting:</p><ul><li>Rejsearrangementer</li><li>Mødetider og -steder</li><li>Udstyrsansvar</li></ul><h2 id="opvarmningsrutinen" tabindex="-1">Opvarmningsrutinen <a class="header-anchor" href="#opvarmningsrutinen" aria-label="Permalink to &quot;Opvarmningsrutinen&quot;">​</a></h2><h3 id="fysisk-opvarmning-15-20-minutter" tabindex="-1">Fysisk opvarmning (15-20 minutter) <a class="header-anchor" href="#fysisk-opvarmning-15-20-minutter" aria-label="Permalink to &quot;Fysisk opvarmning (15-20 minutter)&quot;">​</a></h3><ol><li>Let bevægelse (gang, armcirkler)</li><li>Dynamisk strækning</li><li>Gradvis kastning (kort til lang afstand)</li><li>Kast med fuld intensitet</li></ol><h3 id="mental-opvarmning-5-10-minutter" tabindex="-1">Mental opvarmning (5-10 minutter) <a class="header-anchor" href="#mental-opvarmning-5-10-minutter" aria-label="Permalink to &quot;Mental opvarmning (5-10 minutter)&quot;">​</a></h3><ol><li>Fokusskift til konkurrence</li><li>Kort visualisering</li><li>Positiv selvsnak</li><li>Intentionsindstilling</li></ol><h3 id="terrænfortrolighed" tabindex="-1">Terrænfortrolighed <a class="header-anchor" href="#terrænfortrolighed" aria-label="Permalink to &quot;Terrænfortrolighed&quot;">​</a></h3><ol><li>Observer spillefladen</li><li>Bemærk eventuelle uregelmæssigheder</li><li>Test forskellige områder, hvis det er muligt</li><li>Diskuter observationer med teamet</li></ol><h2 id="almindelige-forberedelsesfejl" tabindex="-1">Almindelige forberedelsesfejl <a class="header-anchor" href="#almindelige-forberedelsesfejl" aria-label="Permalink to &quot;Almindelige forberedelsesfejl&quot;">​</a></h2><h3 id="overtræning" tabindex="-1">Overtræning <a class="header-anchor" href="#overtræning" aria-label="Permalink to &quot;Overtræning&quot;">​</a></h3><p>At forsøge at forbedre sig i de sidste dage fører til træthed, ikke gevinster.</p><h3 id="under-sovning" tabindex="-1">Under-sovning <a class="header-anchor" href="#under-sovning" aria-label="Permalink to &quot;Under-sovning&quot;">​</a></h3><p>At ofre søvn for ekstra træning giver bagslag.</p><h3 id="nye-eksperimenter" tabindex="-1">Nye eksperimenter <a class="header-anchor" href="#nye-eksperimenter" aria-label="Permalink to &quot;Nye eksperimenter&quot;">​</a></h3><p>Konkurrencedagen er ikke til at afprøve nye teknikker eller udstyr.</p><h3 id="ignorerer-nerver" tabindex="-1">Ignorerer nerver <a class="header-anchor" href="#ignorerer-nerver" aria-label="Permalink to &quot;Ignorerer nerver&quot;">​</a></h3><p>Det hjælper ikke at lade som om, du ikke er nervøs. Anerkend og håndter.</p><h3 id="darlig-logistik" tabindex="-1">Dårlig logistik <a class="header-anchor" href="#darlig-logistik" aria-label="Permalink to &quot;Dårlig logistik&quot;">​</a></h3><p>At haste på grund af dårlig planlægning skaber unødvendig stress.</p><h2 id="natten-før" tabindex="-1">Natten før <a class="header-anchor" href="#natten-før" aria-label="Permalink to &quot;Natten før&quot;">​</a></h2><h3 id="gør" tabindex="-1">Gør: <a class="header-anchor" href="#gør" aria-label="Permalink to &quot;Gør:&quot;">​</a></h3><ul><li>Forbered alt hvad du behøver</li><li>Gå i seng til normal tid</li><li>Brug afspændingsteknikker om nødvendigt</li><li>Stol på din forberedelse</li></ul><h3 id="ma-ikke" tabindex="-1">Må ikke: <a class="header-anchor" href="#ma-ikke" aria-label="Permalink to &quot;Må ikke:&quot;">​</a></h3><ul><li>Bliv oppe sent og bekymre dig</li><li>Overanalyser strategi</li><li>Indtage alkohol eller tung mad</li><li>Deltag i stressende aktiviteter</li></ul><h2 id="konkurrencemorgen" tabindex="-1">Konkurrencemorgen <a class="header-anchor" href="#konkurrencemorgen" aria-label="Permalink to &quot;Konkurrencemorgen&quot;">​</a></h2><h3 id="rutinemæssige-anliggender" tabindex="-1">Rutinemæssige anliggender <a class="header-anchor" href="#rutinemæssige-anliggender" aria-label="Permalink to &quot;Rutinemæssige anliggender&quot;">​</a></h3><p>Hold dig til velkendte mønstre:</p><ul><li>Vågn op på det planlagte tidspunkt</li><li>Spis dokumenterede fødevarer</li><li>Følg din normale morgenrutine</li><li>Tag afsted med god tid</li></ul><h3 id="mental-tilstand" tabindex="-1">Mental tilstand <a class="header-anchor" href="#mental-tilstand" aria-label="Permalink to &quot;Mental tilstand&quot;">​</a></h3><p>Dyrk den rette tankegang:</p><ul><li>Spændt, ikke ængstelig</li><li>Selvsikker, ikke arrogant</li><li>Fokuseret, ikke anspændt</li><li>Klar, ikke desperat</li></ul><h2 id="ankomst-til-spillestedet" tabindex="-1">Ankomst til spillestedet <a class="header-anchor" href="#ankomst-til-spillestedet" aria-label="Permalink to &quot;Ankomst til spillestedet&quot;">​</a></h2><ol><li><strong>Sæt dig til rette</strong>: Find din plads, organiser udstyr</li><li><strong>Observer</strong>: Se på terrænet, noter forholdene</li><li><strong>Opvarmning</strong>: Færdiggør din rutine</li><li><strong>Forbind</strong>: Kort teamsammenlægning</li><li><strong>Fokus</strong>: Sidste mentale forberedelse</li></ol><p>Du har forberedt dig godt. Stol nu på det og konkurrer.</p><hr><p>| <em>Relateret: <a href="/da/uddannelse/træning/">Træningsmetoder</a> | <a href="/da/uddannelse/mental-styrke/håndtering-af-pres">Håndtering af pres</a> | <a href="/da/uddannelse/mental-styrke/rutine-før-indtagelse">Rutine før indtagelse</a></em> |</p>',107)])])}]]);export{a as __pageData,n as default};
